"""Upgrade from the 0.7.0 release: its real config.yaml and database (generated by 0.7.0's own code,
see tests/fixtures/upgrade_0_7_0/generate.py) must load with current code, keep every old value, round-trip,
be readable by 0.7.0 again (rollback / downgrade), and survive the updater's backup and restore byte for byte.
Config schema 2 and DB schema 4 are unchanged since 0.7.0, so no migration step runs."""

from __future__ import annotations

import json
import os
import shutil
import sqlite3
import subprocess
import sys
from pathlib import Path

import pytest
import yaml

from stagewatch import backup as bk
from stagewatch import updater_common as uc
from stagewatch.core.config import Config, ConfigStore, migrate
from stagewatch.core.recorder import Recorder
from stagewatch.version import CONFIG_SCHEMA_VERSION, DB_SCHEMA_VERSION

FIX = Path(__file__).parent / "fixtures" / "upgrade_0_7_0"
REPO = Path(__file__).resolve().parent.parent
DB = "stagewatch.sqlite3"


@pytest.fixture
def data(tmp_path):
    d = tmp_path / "data"
    d.mkdir()
    shutil.copyfile(FIX / "config.yaml", d / "config.yaml")
    shutil.copyfile(FIX / DB, d / DB)
    (d / "secret.key").write_bytes(b"fixture-secret-key-bytes\x00\x01")
    (d / "contacts").mkdir()
    (d / "contacts" / "crew.csv").write_text("name,phone\nFixture Person,000\n", encoding="utf-8")
    return d


def counts(path: Path) -> dict[str, int]:
    db = sqlite3.connect(str(path))
    try:
        names = [n for (n,) in db.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
        return {n: db.execute(f"SELECT count(*) FROM {n}").fetchone()[0] for n in names}
    finally:
        db.close()


def old_raw() -> dict:
    return yaml.safe_load((FIX / "config.yaml").read_text(encoding="utf-8"))


def assert_subset(old, new, path="config"):
    """Every value 0.7.0 saved is still there, unchanged (new keys elsewhere are allowed)."""
    if isinstance(old, dict):
        assert isinstance(new, dict), path
        for k, v in old.items():
            assert k in new, f"{path}.{k} lost"
            assert_subset(v, new[k], f"{path}.{k}")
    elif isinstance(old, list) and old and all(isinstance(x, dict) for x in old):
        assert isinstance(new, list) and len(new) == len(old), path
        for i, (o, n) in enumerate(zip(old, new)):
            assert_subset(o, n, f"{path}[{i}]")
    else:
        assert old == new, f"{path}: {old!r} -> {new!r}"


def test_fixture_is_really_0_7_0():
    assert old_raw()["schema_version"] == 2 == CONFIG_SCHEMA_VERSION
    db = sqlite3.connect(str(FIX / DB))
    assert db.execute("PRAGMA user_version").fetchone()[0] == 4 == DB_SCHEMA_VERSION
    db.close()
    assert len(old_raw()["dashboards"]) == 3 and len(old_raw()["esphome_devices"]) == 2


def test_config_loads_keeps_old_values_and_defaults_new_fields(data):
    store = ConfigStore(data / "config.yaml")
    cfg = store.load()
    dumped = cfg.model_dump(mode="json")
    assert_subset(migrate(old_raw()), dumped)
    assert cfg.admin.pin_hash == old_raw()["admin"]["pin_hash"]  # PIN untouched, onboarding stays closed
    assert not store.recovery_required and not store.invalid_files()
    assert cfg.esphome_devices[0].noise_psk == old_raw()["esphome_devices"][0]["noise_psk"]
    assert cfg.dashboards[0].card_sizes == {"wall_clock": "half"}
    fresh = Config().model_dump(mode="json")
    for key in set(fresh) - set(old_raw()):  # a top-level field the file never had comes from its default
        assert dumped[key] == fresh[key], key


def test_load_save_reload_round_trips(data):
    store = ConfigStore(data / "config.yaml")
    first = store.load().model_dump(mode="json")
    store.save()
    again = ConfigStore(data / "config.yaml")
    assert again.load().model_dump(mode="json") == first
    saved = yaml.safe_load((data / "config.yaml").read_text(encoding="utf-8"))
    assert_subset(old_raw(), saved)
    assert saved["schema_version"] == 2


def test_unknown_future_keys_load_and_do_not_disturb_known_ones(data):
    raw = old_raw()
    raw["from_the_future"] = {"x": 1}
    raw["site"]["future_site_option"] = True
    raw["dashboards"][0]["future_dashboard_option"] = "y"
    raw["spl"]["future_spl_option"] = [1, 2]
    raw["esphome_devices"][0]["future_device_option"] = 5
    (data / "config.yaml").write_text(yaml.safe_dump(raw), encoding="utf-8")
    store = ConfigStore(data / "config.yaml")
    cfg = store.load()
    assert not store.recovery_required and not store.invalid_files()
    assert_subset(old_raw(), cfg.model_dump(mode="json"))
    store.save()  # known data survives a save (unknown keys are dropped by design: extra="ignore")
    assert_subset(old_raw(), yaml.safe_load((data / "config.yaml").read_text(encoding="utf-8")))


def test_newer_schema_number_still_loads_known_data(data):
    raw = old_raw()
    raw["schema_version"] = CONFIG_SCHEMA_VERSION + 1
    (data / "config.yaml").write_text(yaml.safe_dump(raw), encoding="utf-8")
    store = ConfigStore(data / "config.yaml")
    cfg = store.load()
    assert cfg.admin.pin_hash and not store.invalid_files()
    assert cfg.site.name == "Fixture Arena"


def test_database_opens_without_migration_and_keeps_every_row(data):
    before = counts(data / DB)
    assert before["states"] == 80 and before["markers"] == 3 and before["alarm_log"] == 2 and before["shows"] == 3
    rec = Recorder(data / DB)
    try:
        assert rec.current_show()["name"] == "Fixture Show Two"  # reopening resumes the latest show
        assert [m.label for m in rec.markers(show_id=2)] == ["Doors", "Support on"]
        assert [m.label for m in rec.markers()] == ["Curfew"]
        assert len(rec.events()) == 2
        db = sqlite3.connect(str(data / DB))
        assert {r[0] for r in db.execute("SELECT event FROM alarm_log")} == {"raised", "cleared"}
        db.close()
        assert {s["name"] for s in rec.shows()} >= {"Fixture Show One", "Fixture Show Two"}
        rec.add_marker("After upgrade", "manual")
    finally:
        rec.close()
    after = counts(data / DB)
    for table, n in before.items():
        assert after[table] >= n, table
    assert after["markers"] == before["markers"] + 1
    db = sqlite3.connect(str(data / DB))
    assert db.execute("PRAGMA user_version").fetchone()[0] == DB_SCHEMA_VERSION
    assert db.execute("PRAGMA integrity_check").fetchone()[0] == "ok"
    db.close()


def test_reopening_is_idempotent(data):
    Recorder(data / DB).close()
    once = counts(data / DB)
    Recorder(data / DB).close()
    assert counts(data / DB) == once


def _backup_and_state(data, tmp_path, backup_id="20261101T000000Z-aaaaaaa-bbbbbbb"):
    state = tmp_path / "state"
    state.mkdir()
    bk.create_backup(data, state, backup_id)
    return state, backup_id


def _snapshot(data: Path) -> dict[str, bytes]:
    return {str(p.relative_to(data)): p.read_bytes() for p in sorted(data.rglob("*"))
            if p.is_file() and "backups" not in p.relative_to(data).parts}


def test_backup_then_rollback_restores_config_and_database_bytes(data, tmp_path):
    ConfigStore(data / "config.yaml").load()
    Recorder(data / DB).close()  # what the new version does on first start
    state, bid = _backup_and_state(data, tmp_path)
    config_before = (data / "config.yaml").read_bytes()
    key_before = (data / "secret.key").read_bytes()
    db_before = (bk.backups_root(data) / bid / DB).read_bytes()
    # the updated version then changes everything
    store = ConfigStore(data / "config.yaml")
    store.load()
    store.config.site.name = "Changed after update"
    store.save()
    rec = Recorder(data / DB)
    rec.add_marker("written after the update", "manual")
    rec.close()
    (data / "contacts" / "crew.csv").write_text("changed", encoding="utf-8")
    assert (data / "config.yaml").read_bytes() != config_before

    displaced = bk.restore_backup(data, state, bid)
    assert (data / "config.yaml").read_bytes() == config_before
    assert (data / "secret.key").read_bytes() == key_before
    assert (data / DB).read_bytes() == db_before
    assert (data / "contacts" / "crew.csv").read_text(encoding="utf-8").startswith("name,phone")
    assert (displaced / DB).is_file()  # the newer data is set aside, not deleted
    assert "Changed after update" in (displaced / "config.yaml").read_text(encoding="utf-8")
    assert counts(data / DB)["markers"] == 3  # the post-update marker is gone from the restored database
    assert ConfigStore(data / "config.yaml").load().site.name == "Fixture Arena"


def test_backup_of_untouched_0_7_0_data_is_byte_exact(data, tmp_path):
    cfg_bytes = (data / "config.yaml").read_bytes()
    state, bid = _backup_and_state(data, tmp_path)
    assert (bk.backups_root(data) / bid / "config.yaml").read_bytes() == cfg_bytes
    bk.verify_backup(data, state, bid)
    assert counts(bk.backups_root(data) / bid / DB) == counts(FIX / DB)


def test_failed_restore_puts_the_data_back(data, tmp_path, monkeypatch):
    state, bid = _backup_and_state(data, tmp_path)
    (data / "config.yaml").write_text("site: {name: Newer}\n", encoding="utf-8")
    before = _snapshot(data)
    real = shutil.copyfile
    calls = {"n": 0}

    def flaky(src, dst, *a, **k):
        calls["n"] += 1
        if calls["n"] == 3:
            raise OSError("disk full")
        return real(src, dst, *a, **k)

    monkeypatch.setattr(shutil, "copyfile", flaky)
    with pytest.raises(uc.UpdaterError):
        bk.restore_backup(data, state, bid)
    monkeypatch.undo()
    assert _snapshot(data) == before  # nothing half-restored, nothing lost


def test_tampered_backup_is_refused_and_leaves_data_alone(data, tmp_path):
    state, bid = _backup_and_state(data, tmp_path)
    (bk.backups_root(data) / bid / "config.yaml").write_text("tampered", encoding="utf-8")
    before = _snapshot(data)
    with pytest.raises(uc.UpdaterError):
        bk.restore_backup(data, state, bid)
    assert _snapshot(data) == before


# ---- the old version must still read what the new one wrote (rollback / failed update) ----

@pytest.fixture(scope="module")
def v070_src(tmp_path_factory):
    git = shutil.which("git")
    if not git or subprocess.run([git, "rev-parse", "-q", "--verify", "refs/tags/v0.7.0"], cwd=REPO,
                                 capture_output=True).returncode != 0:
        pytest.skip("tag v0.7.0 not available in this checkout")
    out = tmp_path_factory.mktemp("sw070")
    tar = out / "src.tar"
    subprocess.run([git, "archive", "-o", str(tar), "v0.7.0", "src"], cwd=REPO, check=True)
    shutil.unpack_archive(str(tar), str(out), format="tar", filter="data")
    return out / "src"


READ_070 = """
import json, sys
from pathlib import Path
import stagewatch
from stagewatch.core.config import ConfigStore
from stagewatch.core.recorder import Recorder
d = Path(sys.argv[1])
assert str(Path(stagewatch.__file__).resolve()).startswith(str(Path(sys.argv[2]).resolve())), stagewatch.__file__
store = ConfigStore(d / 'config.yaml')
cfg = store.load()
rec = Recorder(d / 'stagewatch.sqlite3')
print(json.dumps({'name': cfg.site.name, 'pin': bool(cfg.admin.pin_hash), 'dash': len(cfg.dashboards),
                  'invalid': len(store.invalid_files()), 'markers': len(rec.markers(show_id=None)),
                  'shows': len(rec.shows())}))
rec.close()
"""


def test_0_7_0_reads_data_written_by_current_code(data, v070_src, tmp_path):
    store = ConfigStore(data / "config.yaml")
    store.load()
    store.config.site.name = "Written by new version"
    store.save()
    rec = Recorder(data / DB)
    rec.add_marker("new marker", "manual")
    rec.close()
    script = tmp_path / "read070.py"
    script.write_text(READ_070, encoding="utf-8")
    env = {**os.environ, "PYTHONPATH": str(v070_src)}
    cp = subprocess.run([sys.executable, str(script), str(data), str(v070_src)], env=env,
                        capture_output=True, text=True, timeout=120)
    assert cp.returncode == 0, cp.stderr[-800:]
    got = json.loads(cp.stdout.strip().splitlines()[-1])
    assert got["name"] == "Written by new version"
    assert got["pin"] is True and got["dash"] == 3 and got["invalid"] == 0
    assert got["markers"] == 2 and got["shows"] >= 2  # Curfew + the new marker
